(()=>{'use strict';
 const map=(n,alt)=>`<img class="exam-map" src="learn-assets/exam-map-${n}.svg" alt="${alt}">`;
 const context='中國自改革開放後，整體社會和產業雖然呈現快速發展，但各地因環境條件與限制不同，造成區域發展差異。近年中國為減緩區域發展差異等問題，針對各地區不同的產業特性與問題制定發展策略。右圖為中國四大經濟區分布圖。請問：';
 const questions=[
 {text:'早期中國於東南沿海地區設立經濟特區，吸引外商前往投資玩具、製鞋等工業。該地區具有哪項工業區位優勢？',options:['低廉的勞力','豐富的原料','充足的動力','廣大的市場'],answer:0,explain:'玩具、製鞋等勞力密集產業，需要較多勞動人力，低廉勞力能降低生產成本。'},
 {context,media:map(0,'中國四大經濟區代號圖：甲在西側、乙在中間、丙在東北、丁在東部沿海'),text:'根據圖中代號判斷，甲地區發展困難主要與下列何者有關？',options:['工廠老舊','資源匱乏','勞力高昂','交通不便'],answer:3,explain:'甲為西部地區，地處內陸，對外交通不便。'},
 {context,media:map(0,'中國四大經濟區代號圖：甲在西側、乙在中間、丙在東北、丁在東部沿海'),text:'根據圖中代號判斷，政府對乙地區所提出的對策為下列何者？',options:['強化基礎建設，改善投資環境','利用較低廉的工資，吸引外資','從勞力密集轉型發展高科技產業','提出產業轉型，翻新當地工廠設備'],answer:1,explain:'乙為中部地區，利用工資較東部低廉的優勢吸引外資設廠。'},
 {text:'張老師為了讓同學能了解中國工業發展歷程，特別邀請王同學的奶奶到班上分享職場工作經驗。右圖為當天的互動情形，依圖中資訊判斷，當時中國發展，主要是受下列何項政策所影響？',media:'<div class="exam-comic" role="img" aria-label="漫畫：奶奶說1985～1995年，我在中國的紡織廠擔任管理幹部。學生問當時有很多紡織廠嗎？奶奶回答那時候中國到處都是紡織廠，中國勞工成本低廉，許多外國老闆把工廠遷移至中國發展。"><img src="learn-assets/exam-comic-source.png" alt=""></div>',options:['大躍進運動','西部大開發','設立經濟特區','中部的崛起'],answer:2,explain:'改革開放後，經濟特區利用低廉勞力等優勢吸引外資設廠。'},
 {text:'偉凡規畫到中國設立電子零件代工廠，在某因素的考量下，讓原本想在距離臺灣較近的沿海地區設廠的他，決定將廠區設在內陸地區。上文所述的「某因素」最可能為下列何者？',options:['沿海地區電力不足','沿海地區原料缺乏','內陸地區工資較低','內陸地區土地廣大'],answer:2,explain:'電子零件代工需要勞動人力；內陸工資相對較低，有助降低生產成本。'},
 {text:'2023年中國都市化程度全國平均已達66.2%，若分區來看，各行政區的排名如表。表格內容呈現差異大的現象，下列何者最可能是中國政府對此提出的對策？',media:'<div class="table-scroll"><table><caption>2023年各行政區都市化程度排名（題目提供資料）</caption><thead><tr><th>名次</th><th>前五名</th><th>最後五名</th></tr></thead><tbody>'+[['上海（89.5%）','西藏（38.9%）'],['北京（87.8%）','雲南（53.0%）'],['天津（85.5%）','甘肅（55.5%）'],['廣東（75.4%）','貴州（56.0%）'],['江蘇（75.0%）','廣西（56.8%）']].map((r,i)=>`<tr><td>${i+1}</td><td>${r[0]}</td><td>${r[1]}</td></tr>`).join('')+'</tbody></table></div>',options:['振興東北','中部崛起','西部大開發','設立經濟特區'],answer:2,explain:'最後五名主要位於西部地區，西部大開發旨在促進發展、減緩區域差異。'},
 {text:'1978年以前，中國主要由國家規劃生產與資源分配，並偏重軍事與重工業。這種經濟運作方式稱為什麼？',options:['計畫經濟','加工出口','跨境電商','產業升級'],answer:0,explain:'計畫經濟主要由國家規劃生產與資源分配。'},
 {text:'2010年，中國效法東部經濟帶的發展經驗，在新疆設立哪一個經濟特區？',options:['深圳','廈門','喀什','珠海'],answer:2,explain:'2010年於新疆增設喀什經濟特區。'},
 {text:'臺灣鴻海科技集團是全球最大電子代工企業公司，因中國改革開放，設經濟特區，故其子公司富士康到深圳設廠。近來中國薪資成本改變，該企業過去的優勢不再，另覓別處設廠，最後選址在內陸的山西太原和河南鄭州。右圖為中國四大經濟區分布圖，該企業遷廠方向，最符合下列哪條動線？',media:map(1,'中國四大經濟區代號圖：丙在西側、乙在中間、丁在東北、甲在東部沿海'),options:['甲 → 乙','丙 → 丁','甲 → 丁','乙 → 丙'],answer:0,explain:'深圳位於東部地區甲；太原、鄭州位於中部地區乙。'},
 {text:'東北地區曾是重要的傳統重工業基地，後來面臨礦產枯竭、設備老舊。下列哪項做法最符合振興東北的方向？',options:['持續依賴原有礦產，不必調整','只靠降低工資維持原有生產方式','將所有工廠改成加工出口區','推動產業轉型，例如由傳統汽車業轉向電動車研發'],answer:3,explain:'振興東北著重產業轉型與技術更新。'}
 ];
 const key='geo-industry-final-exam-report-v2';
 let state={answers:Array(10).fill(null),submitted:false,student:{}};
 try{const raw=JSON.parse(sessionStorage.getItem(key)||'null');if(raw&&Array.isArray(raw.answers)&&raw.answers.length===10){state.answers=raw.answers.map(v=>Number.isInteger(v)&&v>=0&&v<4?v:null);state.submitted=raw.submitted===true&&state.answers.every(v=>v!==null);state.student=raw.student||{};state.trainingId=raw.trainingId;state.eventId=raw.eventId;state.received=raw.received===true;state.serverScore=raw.serverScore;}}catch{}
 const save=()=>{try{sessionStorage.setItem(key,JSON.stringify(state));}catch{}};
 function renderExam(){const host=document.getElementById('final-exam');if(!host)return;host.innerHTML='<h2 id="exam-title">自學完成測驗</h2><p>10題，每題10分，共100分。全部作答後交卷。</p><p class="exam-notice"><strong>成績回傳：</strong>交卷會回傳班級、座號、姓名與作答成績。請等畫面顯示「已回傳老師」再關閉。</p><form id="exam-form"><fieldset class="exam-student"><legend>學生資料</legend><label>班級<input id="exam-class" required maxlength="20" autocomplete="off"></label><label>座號<input id="exam-seat" required type="number" min="1" max="99"></label><label>姓名<input id="exam-name" required maxlength="40" autocomplete="off"></label></fieldset>'+questions.map((q,n)=>`<fieldset class="exam-question" id="exam-q-${n}"><legend>第${n+1}題（10分）</legend>${q.context?`<p>${q.context}</p>`:''}<p>${q.text}</p>${q.media||''}<div class="exam-options">${q.options.map((o,i)=>`<label><input type="radio" name="exam-${n}" value="${i}" ${state.answers[n]===i?'checked':''} ${state.submitted?'disabled':''}> <span>(${String.fromCharCode(65+i)}) ${o}</span></label>`).join('')}</div>${state.submitted?`<p class="${state.answers[n]===q.answer?'answer-good':'answer-retry'}">${state.answers[n]===q.answer?'✓ 答對，10分':'答錯，0分'}。正確答案：${String.fromCharCode(65+q.answer)}。${q.explain}</p>`:''}</fieldset>`).join('')+'<p id="exam-message" role="status"></p><button type="submit" class="primary" '+(state.submitted?'hidden':'')+'>交卷並計分</button></form><div id="exam-result" role="status"></div>';
 ['class','seat','name'].forEach(k=>{const el=document.getElementById('exam-'+k);el.value=state.student[k]||'';el.disabled=state.submitted;el.oninput=()=>{state.student[k]=el.value.trim();save();};});
 host.querySelectorAll('input[type="radio"]').forEach(el=>el.onchange=()=>{state.answers[Number(el.name.split('-')[1])]=Number(el.value);save();});
 document.getElementById('exam-form').onsubmit=e=>{e.preventDefault();if(state.submitted)return;const missing=state.answers.findIndex(v=>v===null);if(missing>=0){document.getElementById('exam-message').textContent='第'+(missing+1)+'題尚未作答，請完成全部10題。';document.getElementById('exam-q-'+missing).scrollIntoView({block:'center'});return;}if(!state.student.name||!state.student.class){document.getElementById('exam-message').textContent='請填寫學生資料。';return;}state.submitted=true;state.trainingId=crypto.randomUUID();save();sendExam();renderExam();document.getElementById('exam-result').scrollIntoView({block:'center'});};
 if(state.submitted){const correct=questions.filter((q,i)=>q.answer===state.answers[i]).length;document.getElementById('exam-result').innerHTML=`<h3>測驗成績：${correct*10} / 100分</h3><p>答對 ${correct} / 10題。可回看各題答案與解析。</p><p id="exam-delivery" role="status"></p><button type="button" id="exam-retry">重試回傳</button>`;}
 updateDelivery();
 }

 function updateDelivery(){const el=document.getElementById('exam-delivery'),button=document.getElementById('exam-retry');if(!el)return;const status=window.SELF_STUDY_REPORTER?.status();el.textContent=state.received?'✓ 已回傳老師，試算表已確認收到成績。':status?.busy?'成績回傳中，請稍候……':status?.lastError?'尚未收到老師端確認，成績已保留，請按重試回傳。':'尚未收到老師端確認，成績已保留。';if(button){button.hidden=state.received;button.disabled=!!status?.busy;button.onclick=()=>{sendExam();updateDelivery();};}}
 function sendExam(){if(!state.submitted||state.received)return;const reporter=window.SELF_STUDY_REPORTER;if(!reporter)return;if(state.eventId){reporter.flush();return;}state.trainingId=state.trainingId||crypto.randomUUID();state.eventId=reporter.enqueue({type:'selfStudyExam',examVersion:'industry-self-study-exam-v1',trainingId:state.trainingId,student:{className:state.student.class,seat:String(state.student.seat),name:state.student.name},answers:state.answers.slice()});save();}
 window.addEventListener('self-study-rpc-result',e=>{if(e.detail.eventId!==state.eventId)return;state.received=true;state.serverScore=e.detail.result?.score;save();updateDelivery();});
 window.addEventListener('self-study-delivery-change',updateDelivery);
 const mount=()=>{const h=document.getElementById('final-exam');if(h&&!h.dataset.ready){h.dataset.ready='true';renderExam();}};
 const observer=new MutationObserver(mount);observer.observe(document.getElementById('lesson-content'),{childList:true});mount();
})();
